def softmax(Z):
    Z = np.asarray(Z)
    if Z.ndim == 1:
        Z = Z.reshape(1, -1)
    Z_shifted = Z - np.max(Z, axis=1, keepdims=True)
    exp_Z = np.exp(Z_shifted)
    return exp_Z / np.sum(exp_Z, axis=1, keepdims=True)

def cross_entropy(Z, y):
    Z = np.asarray(Z)
    y = np.asarray(y)
    if Z.ndim == 1:
        Z = Z.reshape(1, -1)
    n = Z.shape[0]
    Z_shifted = Z - np.max(Z, axis=1, keepdims=True)
    log_sum_exp = np.log(np.sum(np.exp(Z_shifted), axis=1)) + np.max(Z, axis=1)
    return np.mean(log_sum_exp - Z[np.arange(n), y])
