        Node(double v, int o, int x = -1, int y = -1) : val(v), grad(0.0), op(o), a(x), b(y) {}
    };
    std::vector<Node> nodes;

    int constant(double v) {
        nodes.emplace_back(v, 0);
        return (int)nodes.size() - 1;
    }
    int input(double v) {
        nodes.emplace_back(v, 1);
        return (int)nodes.size() - 1;
    }
    int add(int a, int b) {
        nodes.emplace_back(nodes[a].val + nodes[b].val, 2, a, b);
        return (int)nodes.size() - 1;
    }
    int mul(int a, int b) {
        nodes.emplace_back(nodes[a].val * nodes[b].val, 3, a, b);
        return (int)nodes.size() - 1;
    }
    int sin_(int a) {
        nodes.emplace_back(std::sin(nodes[a].val), 4, a);
        return (int)nodes.size() - 1;
    }
    int exp_(int a) {
        nodes.emplace_back(std::exp(nodes[a].val), 5, a);
        return (int)nodes.size() - 1;
    }
    double value(int node) const {
        return nodes[node].val;
    }
    void backward(int root) {
        for (auto &n : nodes) n.grad = 0.0;
        nodes[root].grad = 1.0;
        for (int i = (int)nodes.size() - 1; i >= 0; --i) {
            double g = nodes[i].grad;
            if (g == 0.0) continue;
            switch (nodes[i].op) {
                case 2: // add
                    nodes[nodes[i].a].grad += g;
                    nodes[nodes[i].b].grad += g;
                    break;
                case 3: // mul
                    nodes[nodes[i].a].grad += g * nodes[nodes[i].b].val;
                    nodes[nodes[i].b].grad += g * nodes[nodes[i].a].val;
                    break;
                case 4: // sin
                    nodes[nodes[i].a].grad += g * std::cos(nodes[nodes[i].a].val);
                    break;
                case 5: // exp
                    nodes[nodes[i].a].grad += g * nodes[i].val;
